from dataclasses import dataclass,asdict,field
import copy,random
from typing import Any,Optional

BEANS=("Gartenbohne","Rote Bohne","Schwarzaugenbohne","Sojabohne","Brechbohne","Saubohne","Feuerbohne","Blaue Bohne")
COUNTS=dict(zip(BEANS,(6,8,10,12,14,16,18,20)))
METERS={
"Gartenbohne":((2,1),(3,2)),"Rote Bohne":((3,1),(6,2),(8,3),(9,4)),
"Schwarzaugenbohne":((2,1),(4,2),(5,3),(6,4)),"Sojabohne":((2,1),(4,2),(6,3),(7,4)),
"Brechbohne":((3,1),(5,2),(7,3),(8,4)),"Saubohne":((3,1),(5,2),(7,3),(8,4)),
"Feuerbohne":((3,1),(6,2),(8,3),(9,4)),"Blaue Bohne":((4,1),(6,2),(8,3),(10,4))}

@dataclass(frozen=True)
class Action:
