  self.num_players,self.seed=num_players,seed
 def initial_state(self):
  r=random.Random(self.seed); d=[b for b in BEANS for _ in range(COUNTS[b])]; r.shuffle(d); h=[[] for _ in range(self.num_players)]
  for _ in range(5):
   for x in h:x.append(d.pop())
  n=3 if self.num_players==3 else 2
  return GameState(self.num_players,0,"plant",h,[[[] for _ in range(n)] for _ in h],[0]*self.num_players,d,acquired=[[] for _ in h],rng_state=r.getstate())
 def current_player(self,s): return -1 if s.terminal else (s.pending["target"] if s.pending else s.active)
 def _plantable(self,s,p,b): return [i for i,f in enumerate(s.fields[p]) if not f or f[0]==b]
 def _harvestable(self,s,p):
  fs=[(i,f) for i,f in enumerate(s.fields[p]) if f]; protected=any(len(f)>1 for _,f in fs)
  return [i for i,f in fs if len(f)>1 or not protected]
 def legal_actions(self,s):
  if s.terminal:return []
