  p=s.active; a=[Action("harvest",field=i) for i in self._harvestable(s,p)]
  if s.phase=="plant":
   if not s.hands[p]:return a+[Action("finish_planting")]
   b=s.hands[p][0]; a += [Action("plant_hand",bean=b,field=i) for i in self._plantable(s,p,b)]
   if s.planted==1:a.append(Action("finish_planting"))
  elif s.phase=="trade":
   available=sorted(set(s.hands[p]+s.face_up))
   for q in range(s.num_players):
    if q==p:continue
    for g in available:
     a.append(Action("offer_gift",player=q,give=g))
     a += [Action("offer_trade",player=q,give=g,receive=x) for x in sorted(set(s.hands[q]))]
   a.append(Action("finish_trading"))
