   if not s.acquired[p]:a.append(Action("draw_three"))
   else:
    b=s.acquired[p][0]; a += [Action("plant_acquired",bean=b,field=i) for i in self._plantable(s,p,b)]
  return a
 def _draw(self,s,r):
  if not s.deck:
   if not s.discard:return None
   s.deck,s.discard=s.discard,[];r.shuffle(s.deck)
  return s.deck.pop()
