  elif a.kind=="reject_trade":s.pending=None
  elif a.kind=="accept_trade":
   o=s.pending;q=o["target"];g=o["give"];src=s.face_up if g in s.face_up else s.hands[p];src.remove(g);s.acquired[q].append(g)
   if o.get("receive"):s.hands[q].remove(o["receive"]);s.acquired[p].append(o["receive"])
   s.pending=None
